-- =============================================================================
-- Medical 360 Full Database & Schemas Dump
-- Timestamp: 2026-08-21T06:52:08.868Z
-- Compatible with PostgreSQL, MySQL 8+, SQLite, and Cloud SQL
-- =============================================================================

BEGIN;

-- Drop Tables if exists
DROP TABLE IF EXISTS inquiries CASCADE;
DROP TABLE IF EXISTS case_studies CASCADE;
DROP TABLE IF EXISTS doctors CASCADE;
DROP TABLE IF EXISTS hospitals CASCADE;
DROP TABLE IF EXISTS specialties CASCADE;
DROP TABLE IF EXISTS cms_pages CASCADE;

-- 1. Specialties Table
CREATE TABLE specialties (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  name_fr VARCHAR(255),
  name_kr VARCHAR(255),
  short_description TEXT,
  short_description_fr TEXT,
  short_description_kr TEXT,
  description TEXT,
  description_fr TEXT,
  description_kr TEXT,
  icon VARCHAR(64),
  image_url VARCHAR(512),
  popular BOOLEAN DEFAULT FALSE,
  procedures JSON
);

-- 2. Hospitals Table
CREATE TABLE hospitals (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  name_fr VARCHAR(255),
  name_kr VARCHAR(255),
  city VARCHAR(128),
  country VARCHAR(128),
  description TEXT,
  description_fr TEXT,
  description_kr TEXT,
  image_url VARCHAR(512),
  gallery JSON,
  accreditations JSON,
  specialties JSON,
  beds_count INT DEFAULT 0,
  icu_beds INT DEFAULT 0,
  founded_year INT,
  rating DECIMAL(3,2) DEFAULT 5.0,
  review_count INT DEFAULT 0,
  international_patients_per_year INT DEFAULT 0,
  languages JSON,
  featured BOOLEAN DEFAULT FALSE,
  active BOOLEAN DEFAULT TRUE
);

-- 3. Doctors Table
CREATE TABLE doctors (
  id VARCHAR(64) PRIMARY KEY,
  hospital_id VARCHAR(64) REFERENCES hospitals(id) ON DELETE SET NULL,
  name VARCHAR(255) NOT NULL,
  title VARCHAR(255),
  specialties JSON,
  qualifications JSON,
  experience INT DEFAULT 0,
  surgeries INT DEFAULT 0,
  languages JSON,
  image_url VARCHAR(512),
  bio TEXT,
  consultation_fee_usd DECIMAL(10,2) DEFAULT 0.00,
  featured BOOLEAN DEFAULT FALSE
);

-- 4. Case Studies Table
CREATE TABLE case_studies (
  id VARCHAR(64) PRIMARY KEY,
  patient_first_name VARCHAR(128),
  patient_country VARCHAR(128),
  patient_age INT,
  condition VARCHAR(255),
  condition_fr VARCHAR(255),
  condition_kr VARCHAR(255),
  specialty_id VARCHAR(64) REFERENCES specialties(id) ON DELETE SET NULL,
  hospital_id VARCHAR(64) REFERENCES hospitals(id) ON DELETE SET NULL,
  treatment VARCHAR(255),
  treatment_fr VARCHAR(255),
  treatment_kr VARCHAR(255),
  outcome TEXT,
  outcome_fr TEXT,
  outcome_kr TEXT,
  testimonial TEXT,
  testimonial_fr TEXT,
  testimonial_kr TEXT,
  cost_saved_percent INT DEFAULT 0,
  duration_days INT DEFAULT 0,
  year INT,
  image_url VARCHAR(512),
  featured BOOLEAN DEFAULT FALSE
);

-- 5. Inquiries Table
CREATE TABLE inquiries (
  id VARCHAR(64) PRIMARY KEY,
  patient_name VARCHAR(255) NOT NULL,
  patient_email VARCHAR(255),
  patient_phone VARCHAR(64),
  patient_country VARCHAR(128),
  patient_age INT,
  gender VARCHAR(32),
  specialty_id VARCHAR(64),
  hospital_id VARCHAR(64),
  doctor_id VARCHAR(64),
  preferred_language VARCHAR(32),
  medical_condition TEXT,
  symptoms TEXT,
  previous_treatments TEXT,
  budget_usd VARCHAR(64),
  timeframe VARCHAR(64),
  status VARCHAR(64) DEFAULT 'new',
  admin_notes TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 6. CMS Pages Table
CREATE TABLE cms_pages (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  updated_at VARCHAR(64),
  content JSON
);

-- ─── INSERT DATA ───────────────────────────────────────────────────────────

INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-cardiology', 'Cardiology & Cardiac Surgery', 'Cardiologie et Chirurgie Cardiaque', 'Kardiolizi & Sirirzi Leker', 'World-class heart care from diagnosis to complex bypass surgery.', 'Soins cardiaques de classe mondiale, du diagnostic au pontage complexe.', 'Swen leker klas mondial depi test ziska operasion konplex.', 'Our network hospitals offer complete cardiac services — from non-invasive diagnostics and angioplasty to complex bypass grafts (CABG), valve replacements, TAVI, and heart transplants — performed by surgeons with 10,000+ procedure experience.', 'Nos hôpitaux partenaires offrent des services cardiaques complets — du diagnostic non invasif et de l''angioplastie aux pontages complexes (CABG), remplacements de valves, TAVI et greffes cardiaques — réalisés par des chirurgiens ayant plus de 10 000 interventions à leur actif.', 'Nou bann lopital rezo ofer servis leker konple — depi test ziska bypass konplex (CABG), sanzman valv, TAVI ek transplantasion leker — fer par bann sirirzien ki ena lexperyans dan plis ki 10 000 operasion.', 'Heart', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800&q=80', NULL, '[{"id":"proc-c1","specialtyId":"sp-cardiology","name":"Coronary Artery Bypass Graft (CABG)","name_fr":"Pontage Coronarien (CABG)","name_kr":"Bypass Leker (CABG)","description":"Open-heart surgery to restore blood flow to the heart.","description_fr":"Chirurgie à cœur ouvert pour restaurer le flux sanguin vers le cœur.","description_kr":"Operasion leker ouver pou re-donn disan leker.","estimatedDurationDays":10,"estimatedCostUSD":{"min":5000,"max":9000}},{"id":"proc-c2","specialtyId":"sp-cardiology","name":"Angioplasty & Stenting","name_fr":"Angioplastie et Pose de Stent","name_kr":"Anzioplasti & Stent","description":"Minimally invasive procedure to open blocked arteries.","description_fr":"Procédure mini-invasive pour ouvrir les artères bloquées.","description_kr":"Ti-operasion pou debous larter.","estimatedDurationDays":4,"estimatedCostUSD":{"min":3000,"max":6000}},{"id":"proc-c3","specialtyId":"sp-cardiology","name":"Valve Replacement / Repair","name_fr":"Remplacement / Réparation de Valve","name_kr":"Sanzman / Reparasion Valv","description":"Surgical correction of damaged heart valves.","description_fr":"Correction chirurgicale des valves cardiaques endommagées.","description_kr":"Operasion pou repar valv leker ki finn abime.","estimatedDurationDays":12,"estimatedCostUSD":{"min":6000,"max":12000}},{"id":"proc-c4","specialtyId":"sp-cardiology","name":"TAVI (Transcatheter Aortic Valve Implantation)","name_fr":"TAVI (Implantation de Valve Aortique Transcathéter)","name_kr":"TAVI (Inplantasion Valv)","description":"Minimally invasive heart valve replacement without open-heart surgery.","description_fr":"Remplacement de la valve cardiaque de manière mini-invasive sans chirurgie à cœur ouvert.","description_kr":"Sanzman valv leker san bizin ouver leker.","estimatedDurationDays":7,"estimatedCostUSD":{"min":18000,"max":30000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-oncology', 'Oncology & Cancer Care', 'Oncologie et Soins du Cancer', 'Onkolizi & Swen Kanser', 'Advanced cancer diagnosis, treatment, and targeted therapy.', 'Diagnostic du cancer avancé, traitement et thérapie ciblée.', 'Bann test kanser avanse, tretman ek terapi sible.', 'Access cutting-edge cancer treatments including CyberKnife radiosurgery, proton therapy, immunotherapy, targeted therapy, bone marrow transplants, and precision surgery — guided by internationally trained oncologists.', 'Accédez aux traitements de pointe contre le cancer, notamment la radiochirurgie CyberKnife, la protonthérapie, l''immunothérapie, les thérapies ciblées, les greffes de moelle osseuse et la chirurgie de précision — guidés par des oncologues formés à l''international.', 'Gagn akse ar bann tretman kanser de pwent, kouma CyberKnife, proton terapi, immunoterapi, terapi sible, transplantasion mwal ose ek sirirzi presizion — gid par bann spesialis form a linternasional.', 'Microscope', 'https://images.unsplash.com/photo-1584515979956-d9f6e5d09982?w=800&q=80', NULL, '[{"id":"proc-o1","specialtyId":"sp-oncology","name":"Bone Marrow / Stem Cell Transplant","name_fr":"Greffe de Moelle Osseuse / Cellules Souches","name_kr":"Transplantasion Mwal Ose","description":"Treatment for blood cancers including leukemia and lymphoma.","description_fr":"Traitement des cancers du sang, y compris la leucémie et le lymphome.","description_kr":"Tretman pou kanser disan (lesemi ek linfom).","estimatedDurationDays":30,"estimatedCostUSD":{"min":20000,"max":40000}},{"id":"proc-o2","specialtyId":"sp-oncology","name":"CyberKnife Radiosurgery","name_fr":"Radiochirurgie CyberKnife","name_kr":"CyberKnife","description":"Non-invasive tumor removal with pinpoint radiation accuracy.","description_fr":"Ablation non invasive des tumeurs avec une précision de radiation millimétrique.","description_kr":"Bann tretman lasan dimounn san bizin koup dimounn (lasazer).","estimatedDurationDays":7,"estimatedCostUSD":{"min":10000,"max":20000}},{"id":"proc-o3","specialtyId":"sp-oncology","name":"Chemotherapy Programs","name_fr":"Programmes de Chimiothérapie","name_kr":"Program Simioterapi","description":"Personalised chemotherapy cycles for various cancers.","description_fr":"Cycles de chimiothérapie personnalisés pour divers cancers.","description_kr":"Sik simioterapi personalize pou plizier kalite kanser.","estimatedDurationDays":21,"estimatedCostUSD":{"min":2000,"max":8000}},{"id":"proc-o4","specialtyId":"sp-oncology","name":"Immunotherapy","name_fr":"Immunothérapie","name_kr":"Imminoterapi","description":"Harnessing the immune system to fight cancer cells.","description_fr":"Exploitation du système immunitaire pour combattre les cellules cancéreuses.","description_kr":"Fer lekor dimounn re-konbat bann selil kanser.","estimatedDurationDays":14,"estimatedCostUSD":{"min":8000,"max":25000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-orthopedics', 'Orthopedics & Spine', 'Orthopédie et Colonne Vertébrale', 'Ortopedi & Kolonn Vertebral', 'From joint replacements to complex spine surgery.', 'Des remplacements articulaires aux chirurgies complexes de la colonne vertébrale.', 'Depi ranplase zouintir ziska sirirzi konplex ledo.', 'Our partner hospitals perform thousands of knee and hip replacements, robotic joint surgery, and complex spine procedures annually using the latest computer-assisted navigation systems.', 'Nos hôpitaux partenaires réalisent des milliers de remplacements de genou et de hanche, des chirurgies articulaires robotiques et des procédures vertébrales complexes chaque année en utilisant les derniers systèmes de navigation assistés par ordinateur.', 'Nou bann lopital partner fer plizier milye ranplasman zounou ek lans, operasion robotik, ek sirirzi ledo konplex sak lane an itilisan bann sistem navigasyon modern.', 'Bone', 'https://images.unsplash.com/photo-1588776814546-1ffcf47267a5?w=800&q=80', NULL, '[{"id":"proc-or1","specialtyId":"sp-orthopedics","name":"Total Knee Replacement","name_fr":"Remplacement Total du Genou","name_kr":"Sanzman Total Zounou","description":"Surgical replacement of damaged knee joint with prosthetic.","description_fr":"Remplacement chirurgical de l''articulation du genou endommagée par une prothèse.","description_kr":"Sanzman zouintir zounou ki finn abime ek mete enn protez.","estimatedDurationDays":10,"estimatedCostUSD":{"min":4000,"max":8000}},{"id":"proc-or2","specialtyId":"sp-orthopedics","name":"Total Hip Replacement","name_fr":"Remplacement Total de la Hanche","name_kr":"Sanzman Total Lans","description":"Replacement of damaged hip joint to restore mobility.","description_fr":"Remplacement de l''articulation de la hanche endommagée pour restaurer la mobilité.","description_kr":"Sanzman zouintir lans pou regagn mobilite.","estimatedDurationDays":10,"estimatedCostUSD":{"min":4500,"max":9000}},{"id":"proc-or3","specialtyId":"sp-orthopedics","name":"Spine Surgery (TLIF / ALIF)","name_fr":"Chirurgie de la Colonne Vertébrale (TLIF / ALIF)","name_kr":"Sirirzi Ledo (TLIF / ALIF)","description":"Spinal fusion for degenerative disc disease or instability.","description_fr":"Fusion rachidienne pour la maladie dégénérative du disque ou l''instabilité.","description_kr":"Fizion kolonn vertebral pou disk ki finn ize.","estimatedDurationDays":14,"estimatedCostUSD":{"min":6000,"max":14000}},{"id":"proc-or4","specialtyId":"sp-orthopedics","name":"Robotic Knee/Hip Surgery","name_fr":"Chirurgie Robotique Genou/Hanche","name_kr":"Operasion Robotik Zounou/Lans","description":"Computer-guided precision joint replacement surgery.","description_fr":"Chirurgie de remplacement articulaire de précision guidée par ordinateur.","description_kr":"Sirirzi avek lasistans ordinateur pou plis presizion.","estimatedDurationDays":8,"estimatedCostUSD":{"min":7000,"max":12000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-neurology', 'Neurology & Neurosurgery', 'Neurologie et Neurochirurgie', 'Neurolozi & Neuro-Sirirzi', 'Expert care for brain, spine, and nervous system conditions.', 'Soins experts pour les affections du cerveau, de la colonne vertébrale et du système nerveux.', 'Soins lexper pou problem servo, ledo, ek ner.', 'From epilepsy management and stroke rehabilitation to brain tumour surgery and deep brain stimulation, our neurology centres are equipped with 3T MRI, intraoperative neuromonitoring, and expert neurosurgeons.', 'De la gestion de l''épilepsie et de la réadaptation après un AVC à la chirurgie des tumeurs cérébrales et à la stimulation cérébrale profonde, nos centres de neurologie sont équipés d''IRM 3T, de neuromonitoring peropératoire et de neurochirurgiens experts.', 'Pou problem epilepsi, AVC (la stroke), ziska operasion timer dan servo, nou bann sant neurolozi bien ekipe avek masinn modern ek bann meyer spesialis.', 'Brain', 'https://images.unsplash.com/photo-1559757148-5c350d0d3c56?w=800&q=80', NULL, '[{"id":"proc-n1","specialtyId":"sp-neurology","name":"Brain Tumour Surgery","name_fr":"Chirurgie des Tumeurs Cérébrales","name_kr":"Operasion Timer Servo","description":"Microsurgical removal of intracranial tumours.","description_fr":"Ablation microchirurgicale des tumeurs intracrâniennes.","description_kr":"Sirirzi pou tir timer dan servo.","estimatedDurationDays":14,"estimatedCostUSD":{"min":8000,"max":18000}},{"id":"proc-n2","specialtyId":"sp-neurology","name":"Deep Brain Stimulation (DBS)","name_fr":"Stimulation Cérébrale Profonde (DBS)","name_kr":"Stimilasion Servo (DBS)","description":"Treatment for Parkinson''s disease and movement disorders.","description_fr":"Traitement de la maladie de Parkinson et des troubles du mouvement.","description_kr":"Tretman pou maladi Parkinson ek lot problem kontrol.","estimatedDurationDays":10,"estimatedCostUSD":{"min":20000,"max":35000}},{"id":"proc-n3","specialtyId":"sp-neurology","name":"Stroke Rehabilitation","name_fr":"Réadaptation Post-AVC","name_kr":"Tretman Apre Stroke","description":"Intensive neuro-rehabilitation programme post-stroke.","description_fr":"Programme intensif de neuro-réadaptation après un AVC.","description_kr":"Re-adaptasion intensif apre enn kout disan (Stroke).","estimatedDurationDays":21,"estimatedCostUSD":{"min":5000,"max":15000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-transplant', 'Organ Transplants', 'Greffes d''Organes', 'Transplantasion Lorgann', 'Kidney, liver, heart and bone marrow transplant programmes.', 'Programmes de transplantation rénale, hépatique, cardiaque et de moelle osseuse.', 'Program pou transplantasion lerin, fwa, leker ek mwal ose.', 'Our partner hospitals have performed thousands of successful organ transplants with internationally comparable success rates. Full pre-transplant evaluation, surgery, and long-term follow-up coordination.', 'Nos hôpitaux partenaires ont réalisé des milliers de greffes d''organes réussies avec des taux de réussite comparables à l''international. Évaluation pré-greffe complète, chirurgie et coordination du suivi à long terme.', 'Nou bann lopital finn fer milye transplantasion avek sikse mondial. Zot asir test pre-operatwar, operasion, ek swivi lontan.', 'Activity', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=800&q=80', NULL, '[{"id":"proc-t1","specialtyId":"sp-transplant","name":"Kidney Transplant","name_fr":"Greffe de Rein","name_kr":"Transplantasion Lerin","description":"Living or deceased donor kidney transplantation.","description_fr":"Transplantation rénale de donneur vivant ou décédé.","description_kr":"Gref lerin (doner vivan ou ki finn desede).","estimatedDurationDays":21,"estimatedCostUSD":{"min":13000,"max":22000}},{"id":"proc-t2","specialtyId":"sp-transplant","name":"Liver Transplant","name_fr":"Greffe de Foie","name_kr":"Transplantasion Fwa","description":"Living or deceased donor liver transplantation.","description_fr":"Transplantation hépatique de donneur vivant ou décédé.","description_kr":"Gref fwa (doner vivan ou ki finn desede).","estimatedDurationDays":30,"estimatedCostUSD":{"min":28000,"max":45000}},{"id":"proc-t3","specialtyId":"sp-transplant","name":"Bone Marrow Transplant","name_fr":"Greffe de Moelle Osseuse","name_kr":"Transplantasion Mwal Ose","description":"Autologous or allogeneic haematopoietic stem cell transplant.","description_fr":"Transplantation de cellules souches hématopoïétiques autologues ou allogéniques.","description_kr":"Tretman selil sous pou ranplas lezo ki malad.","estimatedDurationDays":35,"estimatedCostUSD":{"min":20000,"max":40000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-ivf', 'Fertility & IVF', 'Fertilité & FIV', 'FIV & Fertilite', 'Advanced fertility treatments with high success rates.', 'Traitements de fertilité avancés avec des taux de réussite élevés.', 'Bann tretman fertilite bien avanse avek to sikse ankor pli o.', 'Our network''s fertility centres offer IVF, ICSI, egg freezing, surrogacy evaluation, and male infertility treatments with internationally competitive success rates and compassionate care.', 'Les centres de fertilité de notre réseau proposent la FIV, l''ICSI, la congélation d''ovules, l''évaluation de la gestation pour autrui et les traitements de l''infertilité masculine avec des taux de réussite internationalement compétitifs et des soins compatissants.', 'Nou bann sant fertilite ofer FIV (in-vitro), ICSI, ek tretman infertilite pou bann misie ek madam avek boukou lafeksion.', 'Baby', 'https://images.unsplash.com/photo-1519689680058-324335c77eba?w=800&q=80', NULL, '[{"id":"proc-i1","specialtyId":"sp-ivf","name":"IVF (In Vitro Fertilisation)","name_fr":"FIV (Fécondation In Vitro)","name_kr":"FIV (Fekondasion In-Vitro)","description":"Complete IVF cycle with embryo transfer.","description_fr":"Cycle complet de FIV avec transfert d''embryon.","description_kr":"Sik FIV konple avek transfer lanbrion.","estimatedDurationDays":21,"estimatedCostUSD":{"min":3000,"max":6000}},{"id":"proc-i2","specialtyId":"sp-ivf","name":"ICSI (Intracytoplasmic Sperm Injection)","name_fr":"ICSI (Injection Intracytoplasmique de Spermatozoïde)","name_kr":"ICSI","description":"Advanced IVF technique for male infertility.","description_fr":"Technique avancée de FIV pour l''infertilité masculine.","description_kr":"Teknik avanse pou misie ki ena difikilte gagn zanfan.","estimatedDurationDays":21,"estimatedCostUSD":{"min":3500,"max":7000}},{"id":"proc-i3","specialtyId":"sp-ivf","name":"Egg / Embryo Freezing","name_fr":"Congélation d''Ovules / Embryons","name_kr":"Friz Dizef / Lanbrion","description":"Fertility preservation for future use.","description_fr":"Préservation de la fertilité pour une utilisation future.","description_kr":"Prezerv fertilite pou itiliz plitar.","estimatedDurationDays":14,"estimatedCostUSD":{"min":2000,"max":4000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-cosmetic', 'Cosmetic & Plastic Surgery', 'Chirurgie Esthétique & Plastique', 'Sirirzi Estetik', 'Premium aesthetic procedures by board-certified surgeons.', 'Procédures esthétiques haut de gamme par des chirurgiens certifiés.', 'Tretman estetik pli top par bann sirirzien sertifie.', 'From rhinoplasty and facelifts to bariatric surgery and body contouring, our cosmetic surgery partners combine artistic precision with clinical excellence at a fraction of European or Mauritian costs.', 'De la rhinoplastie et des liftings à la chirurgie bariatrique et au remodelage corporel, nos partenaires en chirurgie esthétique allient précision artistique et excellence clinique à une fraction des coûts européens ou mauriciens.', 'Nou bann partner sirirzi estetik (rinoplasti, bariatrik) marye presizion artistik ar lekzpertiz klinik, pou enn pri boukou pli bon marse.', 'Sparkles', '/assets/banners/cosmetic_surgery.jpg', NULL, '[{"id":"proc-cs1","specialtyId":"sp-cosmetic","name":"Rhinoplasty (Nose Job)","name_fr":"Rhinoplastie (Chirurgie du Nez)","name_kr":"Rinoplasti (Operasion Nene)","description":"Surgical reshaping of the nose for aesthetic or functional improvement.","description_fr":"Remodelage chirurgical du nez pour une amélioration esthétique ou fonctionnelle.","description_kr":"Sanz form nene pou rezon estetik ouswa medikal.","estimatedDurationDays":7,"estimatedCostUSD":{"min":2500,"max":5000}},{"id":"proc-cs2","specialtyId":"sp-cosmetic","name":"Bariatric Surgery (Gastric Sleeve)","name_fr":"Chirurgie Bariatrique (Sleeve Gastrectomie)","name_kr":"Sirirzi Bariatrik","description":"Weight loss surgery for obesity management.","description_fr":"Chirurgie de perte de poids pour la gestion de l''obésité.","description_kr":"Operasion pou redwir lestoma pou bais pwa.","estimatedDurationDays":7,"estimatedCostUSD":{"min":5000,"max":9000}},{"id":"proc-cs3","specialtyId":"sp-cosmetic","name":"Facelift (Rhytidectomy)","name_fr":"Lifting Facial (Rhytidectomie)","name_kr":"Lifting Figir","description":"Surgical face rejuvenation procedure.","description_fr":"Procédure chirurgicale de rajeunissement du visage.","description_kr":"Operasion pou rann figir paret pli zenn.","estimatedDurationDays":10,"estimatedCostUSD":{"min":3000,"max":7000}}]');
INSERT INTO specialties (id, name, name_fr, name_kr, short_description, short_description_fr, short_description_kr, description, description_fr, description_kr, icon, image_url, popular, procedures) VALUES ('sp-ophthalmology', 'Ophthalmology', 'Ophtalmologie', 'Oftalmolozi (Lizie)', 'Vision correction, cataract surgery, and retinal treatments.', 'Correction de la vue, chirurgie de la cataracte et traitements de la rétine.', 'Tretman lizie, katarak ek laser.', 'State-of-the-art eye care including LASIK/LASEK, cataract surgery with premium IOL implants, retinal detachment repair, glaucoma management, and corneal transplants.', 'Soins oculaires de pointe comprenant LASIK/LASEK, chirurgie de la cataracte avec implants IOL premium, réparation du décollement de la rétine, gestion du glaucome et greffes de cornée.', 'Swen lizie avanse (LASIK, katarak avek inplant, reparasion retin ek transplantasion korne).', 'Eye', 'https://images.unsplash.com/photo-1579684453423-f84349ef60b0?w=800&q=80', NULL, '[{"id":"proc-oph1","specialtyId":"sp-ophthalmology","name":"LASIK Eye Surgery","name_fr":"Chirurgie Oculaire LASIK","name_kr":"Operasion Lizie LASIK","description":"Laser vision correction for myopia, hyperopia and astigmatism.","description_fr":"Correction de la vue au laser pour la myopie, l''hypermétropie et l''astigmatisme.","description_kr":"Koreksion laser pou problem trouvel ek lizie.","estimatedDurationDays":3,"estimatedCostUSD":{"min":800,"max":2500}},{"id":"proc-oph2","specialtyId":"sp-ophthalmology","name":"Cataract Surgery with Premium IOL","name_fr":"Chirurgie de la Cataracte avec IOL Premium","name_kr":"Operasion Katarak","description":"Lens replacement with multifocal intraocular lens.","description_fr":"Remplacement du cristallin par une lentille intraoculaire multifocale.","description_kr":"Ranplas lantiy lizie kan ena katarak.","estimatedDurationDays":3,"estimatedCostUSD":{"min":1500,"max":4000}}]');

INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-1', 'Apollo Hospitals', 'Hôpitaux Apollo', 'Lopital Apollo', 'Chennai', 'India', 'One of Asia''s largest healthcare groups with world-class multi-specialty care. Apollo Hospitals Chennai is a pioneer in organ transplants, cardiac care, and oncology, serving over 100,000 international patients annually.', 'L''un des plus grands groupes de santé d''Asie avec des soins multi-spécialités de classe mondiale. Les Hôpitaux Apollo de Chennai sont pionniers dans les greffes d''organes, les soins cardiaques et l''oncologie, traitant plus de 100 000 patients internationaux par an.', 'Enn bann pli gran group lasante l''Asie avek swen spesialite klas mondial. Lopital Apollo Chennai enn pionie dan transplantasion lorgann, swen leker ek onkolizi. Zot tret plis ki 100 000 pasian etranze sak lane.', 'https://images.unsplash.com/photo-1538108149393-fbbd81895907?w=800&q=80', '["https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=800&q=80","https://images.unsplash.com/photo-1631217868264-e5b90bb7e133?w=800&q=80"]', '["JCI","NABH","ISO 9001"]', '["sp-cardiology","sp-oncology","sp-transplant","sp-orthopedics","sp-neurology"]', 2200, 340, 1983, 4.8, 3240, 42000, '["English","Hindi","French","Arabic","Swahili"]', TRUE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-2', 'Fortis Memorial Research Institute', 'Institut de Recherche Memorial Fortis', 'Lestiti Resers Memorial Fortis', 'Gurugram', 'India', 'Fortis Memorial is a quaternary care multi-super-speciality hospital and a premier referral centre. Known globally for bone marrow transplants, complex cardiac surgeries, and advanced robotic procedures.', 'Fortis Memorial est un hôpital multi-super-spécialités de soins quaternaires et un centre de référence de premier plan. Reconnu mondialement pour les greffes de moelle osseuse, les chirurgies cardiaques complexes et les procédures robotiques avancées.', 'Fortis Memorial se enn gran lopital spesialite. Li rekonet mondialman pou transplantasion mwal ose, sirirzi leker konplex ek operasion robotik avanse.', 'https://images.unsplash.com/photo-1586773860418-d37222d8fce3?w=800&q=80', '["https://images.unsplash.com/photo-1559757175-0eb30cd8c063?w=800&q=80"]', '["JCI","NABH"]', '["sp-cardiology","sp-oncology","sp-orthopedics","sp-neurology","sp-ivf"]', 1000, 180, 2001, 4.7, 2180, 28000, '["English","Hindi","Arabic","French"]', TRUE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-3', 'Bumrungrad International Hospital', 'Hôpital International de Bumrungrad', 'Lopital Internasional Bumrungrad', 'Bangkok', 'Thailand', 'One of Southeast Asia''s premier international hospitals, Bumrungrad treats over 1.3 million patients from 190 countries each year. Renowned for cosmetic surgery, orthopedics, and executive health screenings.', 'L''un des premiers hôpitaux internationaux d''Asie du Sud-Est, Bumrungrad traite plus de 1,3 million de patients de 190 pays chaque année. Réputé pour la chirurgie esthétique, l''orthopédie et les bilans de santé pour cadres.', 'Enn parmi bann pli gran lopital internasional dan l''Asie Sud-Est. Bumrungrad tret plis ki 1.3 milion pasian sak lane. Li bien repite pou sirirzi estetik, ortopedi ek bilan lasante konple.', '/assets/bumrungrad-hospital.jpg', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&q=80"]', '["JCI","ISO 9001"]', '["sp-cosmetic","sp-orthopedics","sp-cardiology","sp-oncology","sp-ophthalmology"]', 580, 120, 1980, 4.9, 5600, 130000, '["English","Thai","Arabic","French","Japanese","Chinese"]', TRUE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-4', 'Gleneagles Hospital', 'Hôpital Gleneagles', 'Lopital Gleneagles', 'Kuala Lumpur', 'Malaysia', 'Gleneagles KL is a world-class hospital known for cardiovascular surgery, orthopedics, and neuroscience. Part of the IHH Healthcare network, one of the world''s largest healthcare groups.', 'Gleneagles KL est un hôpital de classe mondiale reconnu pour la chirurgie cardiovasculaire, l''orthopédie et les neurosciences. Fait partie du réseau IHH Healthcare, l''un des plus grands groupes de santé au monde.', 'Gleneagles KL se enn lopital klas mondial ki konekt ar rezo IHH. Zot bien for dan sirirzi leker, ortopedi ek neurosians.', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800&q=80', '[]', '["JCI","MSQh"]', '["sp-cardiology","sp-orthopedics","sp-neurology","sp-oncology"]', 380, 60, 1996, 4.6, 1890, 22000, '["English","Malay","Mandarin","Tamil","Arabic"]', FALSE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-5', 'Mediclinic City Hospital', 'Hôpital de la Ville Mediclinic', 'Lopital Mediclinic', 'Dubai', 'UAE', 'Located within Dubai Healthcare City, Mediclinic City Hospital is a 280-bed multi-discipline private hospital offering the highest levels of clinical care across more than 50 medical specialties.', 'Situé au sein de la Dubai Healthcare City, l''Hôpital de la Ville Mediclinic est un hôpital privé multidisciplinaire de 280 lits offrant les plus hauts niveaux de soins cliniques dans plus de 50 spécialités médicales.', 'Sitye dan Dubai Healthcare City, lopital prive la ena 280 lili e donn swen pli o nivo dan plis ki 50 spesialite medikal.', 'https://images.unsplash.com/photo-1504439468489-c8920d796a29?w=800&q=80', '[]', '["JCI","CARF"]', '["sp-cardiology","sp-oncology","sp-orthopedics","sp-ivf","sp-cosmetic"]', 280, 40, 2008, 4.5, 1240, 18000, '["English","Arabic","French","Hindi","Urdu"]', FALSE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-6', 'Medanta – The Medicity', 'Medanta – La Médicité', 'Medanta', 'Gurugram', 'India', 'One of India''s largest multi-specialty hospitals, Medanta is founded by renowned cardiac surgeon Dr. Naresh Trehan. World-class for heart surgery, liver transplants, and robotic surgery.', 'L''un des plus grands hôpitaux multi-spécialités de l''Inde, Medanta a été fondé par le célèbre chirurgien cardiaque Dr. Naresh Trehan. De classe mondiale pour la chirurgie cardiaque, les greffes de foie et la chirurgie robotique.', 'Enn parmi bann pli gran lopital l''Inde, fonde par gran dokter leker Dr. Naresh Trehan. Zot top pou operasion leker, transplantasion fwa, ek operasion robotik.', 'https://images.unsplash.com/photo-1512678080530-7760d81faba6?w=800&q=80', '[]', '["JCI","NABH"]', '["sp-cardiology","sp-transplant","sp-oncology","sp-neurology","sp-orthopedics"]', 1600, 250, 2009, 4.8, 2910, 35000, '["English","Hindi","Arabic","French","Swahili"]', TRUE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-7', 'Max Super Speciality Hospital', 'Hôpital Max Super Spécialité', 'Lopital Max', 'New Delhi', 'India', 'Max Saket is among Delhi''s finest hospitals with state-of-the-art infrastructure for bone marrow transplants, neuro-oncology, and spine care. Serves a large Mauritius patient diaspora.', 'Max Saket figure parmi les meilleurs hôpitaux de Delhi avec des infrastructures de pointe pour les greffes de moelle osseuse, la neuro-oncologie et les soins de la colonne vertébrale. Accueille une grande diaspora de patients mauriciens.', 'Max Saket se enn bann meyer lopital dan Delhi. Zot bien avanse pou transplantasion mwal ose ek swen ledo. Zot akey boukou pasian depi Moris.', '/assets/banners/max_hospital.jpg', '[]', '["NABH","ISO 9001"]', '["sp-oncology","sp-neurology","sp-orthopedics","sp-cardiology"]', 500, 80, 1985, 4.5, 1670, 20000, '["English","Hindi","French","Arabic"]', FALSE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-8', 'Mount Elizabeth Hospital', 'Hôpital Mount Elizabeth', 'Lopital Mount Elizabeth', 'Singapore', 'Singapore', 'Singapore''s leading private hospital renowned for complex cancer care, cardiovascular procedures, and neurosurgery. Strict international quality standards and cutting-edge diagnostics.', 'Principal hôpital privé de Singapour, reconnu pour les soins complexes du cancer, les procédures cardiovasculaires et la neurochirurgie. Normes de qualité internationales strictes et diagnostics de pointe.', 'Lopital prive nimer 1 dan Singapour, bien rekonet pou tretman kanser konplex, sirirzi leker, ek operasion servo. Bann standar kalite bien strik.', 'https://images.unsplash.com/photo-1530497610245-94d3c16cda28?w=800&q=80', '[]', '["JCI","ISO 9001"]', '["sp-oncology","sp-cardiology","sp-neurology","sp-orthopedics"]', 505, 90, 1979, 4.9, 4200, 55000, '["English","Mandarin","Malay","Tamil","Arabic","French"]', TRUE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-9', 'Manipal Hospitals', 'Hôpitaux Manipal', 'Lopital Manipal', 'Bangalore', 'India', 'Manipal Old Airport Road is a 600+ bed multi-speciality hospital with advanced robotic surgery capabilities, organ transplant programs, and strong IVF & fertility success rates.', 'Manipal Old Airport Road est un hôpital multi-spécialités de plus de 600 lits doté de capacités avancées de chirurgie robotique, de programmes de transplantation d''organes et de taux de réussite élevés en FIV et fertilité.', 'Manipal se enn gran lopital avek plis ki 600 lili. Zot ena operasion robotik avanse, program transplantasion lorgann ek enn bon to sikse pou FIV ek fertilite.', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800&q=80', '[]', '["NABH","ISO 9001"]', '["sp-ivf","sp-transplant","sp-oncology","sp-orthopedics","sp-cosmetic"]', 650, 100, 1991, 4.6, 1980, 24000, '["English","Hindi","Kannada","French","Arabic"]', FALSE, TRUE);
INSERT INTO hospitals (id, name, name_fr, name_kr, city, country, description, description_fr, description_kr, image_url, gallery, accreditations, specialties, beds_count, icu_beds, founded_year, rating, review_count, international_patients_per_year, languages, featured, active) VALUES ('hosp-10', 'Artemis Hospital', 'Hôpital Artemis', 'Lopital Artemis', 'Gurugram', 'India', 'Artemis is NCR''s first hospital to be accredited by JCI, known for spine surgery, kidney transplants, and a dedicated International Patient Centre that assists Mauritius and African patients.', 'Artemis est le premier hôpital de la RCN à être accrédité par la JCI. Il est reconnu pour la chirurgie de la colonne vertébrale, les greffes de reins et son Centre dédié aux Patients Internationaux qui assiste les patients mauriciens et africains.', 'Artemis se premie lopital NCR ki finn gagn akreditasion JCI. Zot konekt avek pasian Moris ek l''Afrique, sirtou pou operasion ledo ek transplantasion lerin.', 'https://images.unsplash.com/photo-1590856029826-c7a73142bbf1?w=800&q=80', '[]', '["JCI","NABH"]', '["sp-transplant","sp-neurology","sp-orthopedics","sp-cardiology"]', 400, 65, 2007, 4.4, 1120, 15000, '["English","Hindi","French","Arabic","Swahili"]', FALSE, TRUE);

INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-1', 'hosp-narayana', 'Dr. Devi Prasad Shetty', 'Chairman & Chief Cardiac Surgeon', '["sp-cardiology"]', '["MBBS","MS (General Surgery)","FRCS (Cardiothoracic Surgery - UK)"]', 36, 15000, '["English","Hindi","Kannada"]', 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=800&q=80', 'World-renowned cardiothoracic surgeon who has performed over 15,000 heart surgeries. Pioneer of high-volume, low-cost micro-precision cardiac care assisting patients across the Indian Ocean.', 60, TRUE);
INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-2', 'hosp-medanta', 'Dr. Naresh Trehan', 'Chairman & Managing Director, Cardiovascular Surgeon', '["sp-cardiology"]', '["MBBS","Diplomate American Board of Surgery","Diplomate American Board of Cardiothoracic Surgery"]', 42, 48000, '["English","Hindi","Punjabi"]', 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?w=800&q=80', 'Former Assistant Professor of Surgery at NYU Medical Center. Pioneered robotic heart surgery and minimally invasive coronary artery bypass surgery in Asia.', 75, TRUE);
INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-3', 'hosp-bumrungrad', 'Dr. Suthep Udomsawaengsup', 'Director of Advanced Minimally Invasive & Bariatric Surgery', '["sp-oncology","sp-orthopedics"]', '["MD (Chulalongkorn)","Fellow of American College of Surgeons (FACS)","Fellowship in Laparoscopic Surgery (USA)"]', 25, 8500, '["English","Thai","French (Basic)"]', 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=800&q=80', 'Renowned expert in robotic surgical oncology and complex minimally invasive surgical interventions with international training in the United States and Japan.', 80, TRUE);
INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-4', 'hosp-gleneagles', 'Dr. Wong Chiung Ing', 'Senior Consultant Medical Oncologist', '["sp-oncology"]', '["MB ChB (UK)","MRCP (UK)","FAMS (Medical Oncology)"]', 22, 4200, '["English","Mandarin","Cantonese","Malay"]', '/assets/banners/dr_wong_chiung_ing.jpg', 'Distinguished oncologist specializing in targeted therapies, precision immunotherapy, and breast, lung, and gastrointestinal cancers at Gleneagles Singapore.', 95, TRUE);
INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-5', 'hosp-apollo-chennai', 'Prof. Dr. Subhash Gupta', 'Chairman - Liver Transplant & Hepato-Pancreato-Biliary Surgery', '["sp-transplant"]', '["MBBS","MS","FRCS (Edinburgh)","FRCS (Glasgow)"]', 31, 6000, '["English","Hindi","Tamil"]', 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=800&q=80', 'Pioneering liver transplant surgeon who led the first successful living donor liver transplant programs across South Asia with over 3,000 successful liver transplants.', 70, TRUE);
INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-6', 'hosp-fortis', 'Dr. Firuza R. Parikh', 'Director - Assisted Reproduction & Genetics (IVF)', '["sp-ivf"]', '["MD (Obstetrics & Gynaecology)","DGO","Diplomate of National Board","Postdoctoral Fellow (Yale University, USA)"]', 34, 12000, '["English","Hindi","Gujarati","French"]', 'https://images.unsplash.com/photo-1582750433449-648ed127bb54?w=800&q=80', 'Internationally acclaimed fertility specialist trained at Yale University School of Medicine. Has helped deliver over 12,000 babies to couples across 35 countries.', 65, TRUE);
INSERT INTO doctors (id, hospital_id, name, title, specialties, qualifications, experience, surgeries, languages, image_url, bio, consultation_fee_usd, featured) VALUES ('doc-7', 'hosp-apollo-delhi', 'Dr. Arun Saroha', 'Senior Director - Neurosurgery & Spine Surgery', '["sp-neurology"]', '["MBBS","MS (General Surgery)","MCh (Neurosurgery - PGI Chandigarh)"]', 24, 9000, '["English","Hindi"]', 'https://images.unsplash.com/photo-1622253694242-abeb37a33e97?w=800&q=80', 'Leading neurosurgeon and spine specialist specializing in minimally invasive brain tumor resections, complex spinal reconstructions, and neuro-endoscopy.', 60, TRUE);

INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-1', 'Marie-Claire', 'Mauritius', 58, 'Triple Vessel Coronary Artery Disease', 'Maladie Coronarienne Tritronculaire', 'Maladi Leker (3 Larter Bouse)', 'sp-cardiology', 'hosp-1', 'Triple Bypass Surgery (CABG)', 'Triple Pontage Coronarien (CABG)', 'Operasion Bypass Leker', 'Full recovery in 3 weeks. Returned to Mauritius with complete heart function restored. Follow-up confirmed excellent graft patency.', 'Rétablissement complet en 3 semaines. Retournée à l''île Maurice avec une fonction cardiaque entièrement restaurée. Le suivi a confirmé une excellente perméabilité des greffons.', 'Retabli net dan 3 semenn. Retourn Moris avek so leker ki pe bat bien. Test apre montre ki tout korek.', 'I was told in Mauritius that I needed surgery urgently but the wait was long. Medical 360 arranged everything within a week. Apollo''s team was outstanding — I felt cared for from the moment I landed.', 'On m''a dit à l''île Maurice que j''avais besoin d''une opération en urgence, mais l''attente était longue. Medical 360 a tout organisé en une semaine. L''équipe d''Apollo était exceptionnelle — je me suis sentie prise en charge dès mon arrivée.', 'Dokter Moris ti dir mwa bizin oper an-irzans me ti pou bizin atann lontan. Medical 360 finn fer tou dan enn semenn. Lekip Apollo top — zot inn bien get mwa depi mo desann avion.', 65, 18, 2024, 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=800&q=80', TRUE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-2', 'Rajesh', 'Mauritius', 45, 'Chronic Kidney Failure (Stage 5)', 'Insuffisance Rénale Chronique (Stade 5)', 'Problem Lerin Kronic (Stad 5)', 'sp-transplant', 'hosp-6', 'Living Donor Kidney Transplant', 'Greffe de Rein (Donneur Vivant)', 'Transplantasion Lerin (Doner Vivan)', 'Successful transplant with brother as donor. Creatinine levels normalised within 6 days. Discharged after 16 days.', 'Greffe réussie avec son frère comme donneur. Les niveaux de créatinine se sont normalisés en 6 jours. Sortie de l''hôpital après 16 jours.', 'Transplantasion korek avek so frer. Kreyatinin inn vinn normal dan 6 zour. Sorti lopital apre 16 zour.', 'Medanta''s transplant team coordinated everything for us — my brother and I flew together. The entire team spoke French which made us both feel at ease.', 'L''équipe de transplantation de Medanta a tout coordonné pour nous — mon frère et moi avons voyagé ensemble. Toute l''équipe parlait français, ce qui nous a mis à l''aise tous les deux.', 'Lekip Medanta inn organiz tou pou nou — mo frer ek mwa inn voyaze ansam. Tou dimounn ti pe koz franse ek sa finn met nou bien a lez.', 60, 22, 2024, 'https://images.unsplash.com/photo-1612531385446-f7e6d131e1d0?w=800&q=80', TRUE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-3', 'Nathalie', 'Réunion Island', 38, 'Primary Infertility (3 failed IVF cycles)', 'Infertilité Primaire (3 cycles de FIV échoués)', 'Problem Gagn Zanfan (3 FIV pa finn marse)', 'sp-ivf', 'hosp-9', 'Advanced IVF with PGT-A (Preimplantation Genetic Testing)', 'FIV avancée avec PGT-A (Test Génétique Préimplantatoire)', 'FIV avanse avek Test Zenetik (PGT-A)', 'Successful pregnancy achieved on first cycle at Manipal. Delivered a healthy baby girl 9 months later.', 'Grossesse réussie dès le premier cycle chez Manipal. A donné naissance à une petite fille en bonne santé 9 mois plus tard.', 'Tomansint depi premie esey Manipal. Finn gagn enn tifi an bonn-sante 9 mwa apre.', 'After 3 failed attempts elsewhere, Medical 360 connected us with a specialist who changed our protocol completely. We are now a family of three.', 'Après 3 tentatives échouées ailleurs, Medical 360 nous a mis en contact avec un spécialiste qui a complètement changé notre protocole. Nous sommes maintenant une famille de trois.', 'Apre ki nou finn al faya 3 fwa lot plas, Medical 360 finn refer nou enn dokter ki finn sanz tou. Zordi nou enn fami trwa dimounn.', 55, 25, 2023, 'https://images.unsplash.com/photo-1491013516836-7db643ee125a?w=800&q=80', TRUE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-4', 'Ahmed', 'Mauritius', 62, 'Stage III Colorectal Cancer', 'Cancer Colorectal de Stade III', 'Kanser Kolon Stad III', 'sp-oncology', 'hosp-8', 'Laparoscopic Colectomy + Adjuvant Chemotherapy', 'Colectomie Laparoscopique + Chimiothérapie Adjuvante', 'Sirirzi Laparoskopik + Simioterapi', 'Tumour removed with clear margins. 6 cycles of chemotherapy completed. Currently in remission after 18 months.', 'Tumeur retirée avec des marges saines. 6 cycles de chimiothérapie complétés. Actuellement en rémission après 18 mois.', 'Finn tir timer la bien prop. 6 sik simioterapi finn termine. Kanser la finn disparet apre 18 mwa.', 'Mount Elizabeth in Singapore gave us hope when we had almost none. Medical 360''s team handled every detail so my family could focus on my recovery.', 'Mount Elizabeth à Singapour nous a redonné espoir alors que nous n''en avions presque plus. L''équipe de Medical 360 a géré chaque détail pour que ma famille puisse se concentrer sur ma guérison.', 'Mount Elizabeth Singapour ti donn nou lespwar kan nou ti napa ditou. Lekip Medical 360 finn deal tou detay pou mo fami konsantre zis lor mo gerizon.', 40, 45, 2023, 'https://images.unsplash.com/photo-1582719471384-894fbb16e074?w=800&q=80', TRUE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-5', 'Priya', 'Mauritius', 52, 'Severe Bilateral Knee Osteoarthritis', 'Arthrose Sévère Bilatérale du Genou', 'Zounou bien ize (Tou-le-de Kote)', 'sp-orthopedics', 'hosp-3', 'Bilateral Total Knee Replacement (Robotic-assisted)', 'Remplacement Total Bilatéral du Genou (Assisté par Robot)', 'Sanz Zounou (Avek Ed Robot)', 'Walking without aid by day 7 post-surgery. Returned to Mauritius at day 14. Resumed normal activities at 6 weeks.', 'Marchait sans aide dès le 7ème jour post-opératoire. Retour à l''île Maurice au 14ème jour. Reprise des activités normales à 6 semaines.', 'Finn komanse marse san beki zour 7 apre operasion. Retourn Moris zour 14. Repran lavi normal dan 6 semenn.', 'Bumrungrad is world-class. The physiotherapy team started working with me the same day as surgery. I wish I had done it sooner.', 'Bumrungrad est de classe mondiale. L''équipe de physiothérapie a commencé à travailler avec moi le jour même de l''opération. J''aurais aimé le faire plus tôt.', 'Bumrungrad klas mondial. Lekip fizioterapi ti koumans travay ar mwa mem zour mo finn opere. Mo ti bizin fer sa bien avan.', 70, 14, 2024, 'https://images.unsplash.com/photo-1571772996211-2f02c9727629?w=800&q=80', TRUE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-6', 'Jean-Louis', 'Mauritius', 34, 'L4-L5 Disc Herniation with Severe Sciatica', 'Hernie Discale L4-L5 avec Sciatique Sévère', 'Erni Diskal (L4-L5) avek douler Siyatik', 'sp-orthopedics', 'hosp-10', 'Minimally Invasive Microdiscectomy', 'Microdiscectomie Mini-invasive', 'Ti-operasion pou netway Disk', 'Complete pain relief within 48 hours of surgery. Discharged day 5. Resumed desk work at 3 weeks.', 'Soulagement complet de la douleur dans les 48 heures suivant la chirurgie. Sortie de l''hôpital au 5ème jour. Reprise du travail de bureau à 3 semaines.', 'Tou douler inn disparet dan 48h apre operasion. Sorti lopital zour 5. Repran travay lofis 3 semenn plitar.', 'I had been in pain for 2 years. Medical 360 arranged my consultation and surgery within 10 days of my first call. Artemis treated me like family.', 'J''avais mal depuis 2 ans. Medical 360 a organisé ma consultation et mon opération dans les 10 jours suivant mon premier appel. Artemis m''a traité comme un membre de la famille.', 'Mo ti pe soufer pandan 2 an. Medical 360 ti organiz mo rande-vou ek operasion an 10 zour. Artemis ti tret mwa kouma enn manm zot fami.', 62, 8, 2024, 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&q=80', FALSE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-7', 'Fatima', 'Comoros', 29, 'Corneal Blindness (Right Eye)', 'Cécité Cornéenne (Œil Droit)', 'Problem Korne (Lizie Drwat Aveg)', 'sp-ophthalmology', 'hosp-4', 'Penetrating Keratoplasty (Corneal Transplant)', 'Kératoplastie Transfixiante (Greffe de Cornée)', 'Transplantasion Korne', 'Vision restored to 6/9 in operated eye. No rejection in 12-month follow-up. Life-changing outcome.', 'Vision restaurée à 6/9 dans l''œil opéré. Aucun rejet lors du suivi à 12 mois. Un résultat qui change la vie.', 'Lizie pe trouve bien (6/9). Pena okenn reze korne 12 mwa apre. Lavi inn sanz net.', 'I never thought I would see clearly again. Medical 360 arranged the donor cornea matching and surgery in Kuala Lumpur. I am so grateful.', 'Je n''aurais jamais pensé revoir clairement un jour. Medical 360 a organisé la compatibilité de la cornée du donneur et la chirurgie à Kuala Lumpur. Je suis si reconnaissante.', 'Zame mo ti panse mo ti pou trouv kler ankor. Medical 360 finn trouv enn doner korne ek organiz tou Kuala Lumpur. Mo extra rekonesan.', 58, 12, 2023, '/assets/banners/corneal_case_study.jpg', FALSE);
INSERT INTO case_studies (id, patient_first_name, patient_country, patient_age, condition, condition_fr, condition_kr, specialty_id, hospital_id, treatment, treatment_fr, treatment_kr, outcome, outcome_fr, outcome_kr, testimonial, testimonial_fr, testimonial_kr, cost_saved_percent, duration_days, year, image_url, featured) VALUES ('cs-8', 'Bernard', 'Mauritius', 67, 'Parkinson''s Disease (Advanced)', 'Maladie de Parkinson (Avancée)', 'Maladi Parkinson (Avanse)', 'sp-neurology', 'hosp-6', 'Deep Brain Stimulation (DBS)', 'Stimulation Cérébrale Profonde (DBS)', 'Stimilasion Servo (DBS)', 'Tremors reduced by 85%. Medication reduced by half. Independent daily living restored after 3 months.', 'Tremblements réduits de 85 %. Médicaments réduits de moitié. Vie quotidienne indépendante restaurée après 3 mois.', 'Tranblema finn bais par 85%. Kuantite medsinn finn koup an-de. Repran lavi normal ek indepandan 3 mwa apre.', 'My family had watched me deteriorate for 5 years. Medical 360 found us a specialist who said I was an ideal DBS candidate. That decision changed everything.', 'Ma famille m''avait regardé me détériorer pendant 5 ans. Medical 360 nous a trouvé un spécialiste qui a dit que j''étais un candidat idéal pour la DBS. Cette décision a tout changé.', 'Mo fami ti pe trouv mwa degrade depi 5 an. Medical 360 finn trouv enn dokter ki finn trouv mwa bon pou fer DBS. Sa ti sanz mo lavi net.', 55, 14, 2023, 'https://images.unsplash.com/photo-1559757175-0eb30cd8c063?w=800&q=80', FALSE);

