INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('header', 'header', '2026-08-21T06:52:08.868Z', '{"brandName":{"en":"Medical","fr":"Medical","kr":"Medical"},"brandSuffix":{"en":"360","fr":"360","kr":"360"},"emergencyText":{"en":"24/7 Patient Assistance","fr":"Assistance Patient 24/7","kr":"Asistans Pasian 24/7"},"phoneNumber":{"en":"+230 59188275","fr":"+230 59188275","kr":"+230 59188275"},"whatsAppText":{"en":"WhatsApp Us","fr":"WhatsApp","kr":"WhatsApp Nou"},"navAbout":{"en":"About Us","fr":"À Propos","kr":"Lor Nou"},"navHospitals":{"en":"Hospitals","fr":"Hôpitaux","kr":"Lopital"},"navSpecialties":{"en":"Specialties","fr":"Spécialités","kr":"Spesialite"},"navDoctors":{"en":"Specialists","fr":"Médecins","kr":"Bann Dokter"},"navServices":{"en":"Services","fr":"Services","kr":"Servis"},"navCaseStudies":{"en":"Patient Stories","fr":"Témoignages","kr":"Zistwar Pasian"},"navContact":{"en":"Contact","fr":"Contact","kr":"Kontak"},"navFreeOpinionBtn":{"en":"Get Free Opinion","fr":"Avis Gratuit","kr":"Lavi Medikal Gratis"}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('home', 'home', '2026-08-21T06:52:08.868Z', '{"heroBadge":{"en":"✦ Mauritius''s Trusted Medical Concierge","fr":"✦ Votre Conciergerie Médicale de Confiance à l''Île Maurice","kr":"✦ Ou Konzierz Medikal de Konfians dan Moris"},"heroTitleLine1":{"en":"World-Class Healthcare,","fr":"Des Soins de Classe Mondiale,","kr":"Swen Lasante Kalite,"},"heroTitleLine2":{"en":"Without the Wait","fr":"Sans Attente","kr":"San Bizin Atann"},"heroSubtitle":{"en":"Connecting patients from Mauritius to leading accredited hospitals globally. Get expert medical opinions, transparent pricing, and comprehensive travel coordination—all for free.","fr":"Connecter les patients de l''île Maurice aux principaux hôpitaux accrédités dans le monde entier. Obtenez des avis médicaux d''experts, des prix transparents et une coordination de voyage complète, tout cela gratuitement.","kr":"Konekte bann pasian Moris ar bann pli bon lopital dan lemond. Gagn bann lavi expert medikal, pri kler, ek kordinasion voyaz — tou sa pou nanye."},"heroBannerImage":{"en":"https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1600&q=80","fr":"https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1600&q=80","kr":"https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1600&q=80"},"trustText":{"en":"Trusted by 1,200+ Mauritian Patients","fr":"Approuvé par plus de 1 200 patients mauriciens","kr":"Plis ki 1,200 pasian Morisien fer nou konfians"},"statPatients":{"en":"1,200+ Patients Assisted","fr":"1 200+ Patients Accompagnés","kr":"1,200+ Pasian Asiste"},"statHospitals":{"en":"15+ Accredited Hospitals","fr":"15+ Hôpitaux Accrédités","kr":"15+ Lopital Akredite"},"statCountries":{"en":"7+ Global Destinations","fr":"7+ Destinations Mondiales","kr":"7+ Destinasion Mondial"},"statSatisfaction":{"en":"100% Satisfaction Rate","fr":"100% Taux de Satisfaction","kr":"100% Pousantaz Satisfe"},"processLabel":{"en":"Simple 4-Step Process","fr":"Processus en 4 Étapes","kr":"Prosesis an 4 Letap"},"processTitle":{"en":"Your Healthcare Journey in 4 Simple Steps","fr":"Votre Parcours de Soins en 4 Étapes Simples","kr":"Ou Vwayaz Lasante an 4 Letap"},"processStep1Title":{"en":"1. Describe Your Need","fr":"1. Décrivez Votre Besoin","kr":"1. Dekrir Ou Bizin"},"processStep1Desc":{"en":"Fill our simple medical inquiry form with your condition, specialty, and preferences.","fr":"Remplissez notre formulaire de demande médicale simple avec votre condition, votre spécialité et vos préférences.","kr":"Ranpli nou form sinp ek dekrir ou maladi, spesialite, ek ou preferans."},"processStep2Title":{"en":"2. Get a Free Opinion","fr":"2. Obtenez un Avis Gratuit","kr":"2. Gagn Lavi Gratis"},"processStep2Desc":{"en":"Our medical team reviews your case and recommends the best hospitals and specialists within 48 hours.","fr":"Notre équipe médicale examine votre cas et vous recommande les meilleurs hôpitaux et spécialistes sous 48h.","kr":"Nou lekip medikal get ou dosie e rekomann bann pli bon lopital ek dokter dan 48h."},"processStep3Title":{"en":"3. We Plan Everything","fr":"3. Nous Planifions Tout","kr":"3. Nou Planifie Tou"},"processStep3Desc":{"en":"Appointment, visa support, flights, hotel, and airport transfers — all coordinated by Med360.","fr":"Rendez-vous, demande de visa, vols, hôtels et transferts aéroport — tout est coordonné par Med360.","kr":"Randevou, viza, biye avion, lotel, ek transpor — Med360 okip tou."},"processStep4Title":{"en":"4. Travel & Recover","fr":"4. Voyagez et Récupérez","kr":"4. Voyaz ek Repoze"},"processStep4Desc":{"en":"Arrive with confidence. Our dedicated coordinator stays with you throughout your treatment.","fr":"Arrivez en toute confiance. Notre coordinateur dédié reste avec vous tout au long de votre traitement.","kr":"Voyaz san traka. Nou kordinater dedie res avek ou pandan tou ou tretman."},"whyBadge":{"en":"Why Choose Medical 360","fr":"Pourquoi Choisir Medical 360","kr":"Kifer Swazir Medical 360"},"whyTitle":{"en":"Your Health. Our Lifelong Mission.","fr":"Votre Santé. Notre Mission de Vie.","kr":"Ou Lasante. Nou Mision."},"whyDesc":{"en":"We are your trusted health partner. From finding the right surgeon to coordinating every flight and hotel, we handle the stress so you can focus on healing.","fr":"Nous sommes votre partenaire santé de confiance. De la recherche du bon chirurgien à la réservation des vols et hôtels, nous gérons tout le stress pour vous.","kr":"Nou ou partner lasante de konfians. Depi trouv bon dokter ziska rezerv vol ek lotel, nou okip tou pou ou kapav zis konsantre lor ou gerizon."},"consultationTitle":{"en":"Comprehensive Support at Every Step","fr":"Un Accompagnement Complet à Chaque Étape","kr":"Enn Soutien Konple Dan Sak Letap"},"consultationDesc":{"en":"Our dedicated patient coordinators assist you with hospital admission, translation, accommodation, and post-discharge recovery care.","fr":"Nos coordinateurs dédiés vous accompagnent pour l''admission, la traduction, le logement et les soins post-opératoires.","kr":"Nou bann kordinater dedie ed ou pou ladmision lopital, tradiksion, lakozman, ek swen rekiperasion apre tretman."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('about', 'about', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"Our Story & Purpose","fr":"Notre Histoire & Notre Mission","kr":"Nou Zistwar & Nou Lobzektif"},"heroTitle":{"en":"About Medical 360","fr":"À Propos de Medical 360","kr":"A Propo Medical 360"},"heroDesc":{"en":"Med360 Ltd was founded with a clear mission: to ensure every patient in Mauritius and the Indian Ocean region has access to the world''s finest healthcare.","fr":"Med360 Ltd a été fondée avec une mission claire : garantir à chaque patient de l''Île Maurice et de l''océan Indien l''accès aux meilleurs soins de santé mondiaux.","kr":"Med360 Ltd ti kree avek enn sel lobzektif: fer sir ki sak pasian dan Moris ek l''osean Indien gagn akse ar bann meyer swen lasante klas mondial."},"missionLabel":{"en":"Our Core Mission","fr":"Notre Mission Principale","kr":"Nou Mision Prinsipal"},"missionTitle":{"en":"Bridging Mauritius to World-Class Healthcare","fr":"Relier l''Île Maurice aux Soins Mondiaux","kr":"Konekt Moris ar Swen Klas Mondial"},"missionP1":{"en":"Medical 360 was founded with a clear mission: to ensure that every patient in Mauritius and the Indian Ocean region has access to the world''s best healthcare — regardless of what is available locally.","fr":"Medical 360 a été fondée avec une mission claire : veiller à ce que chaque patient de l''Île Maurice et de l''océan Indien ait accès aux meilleurs soins mondiaux — indépendamment de ce qui est disponible localement.","kr":"Medical 360 ti fonde avek enn mision bien kler: fer sir ki sak pasian dan Moris ek l''osean Indien gagn akse ar bann meyer swen mondial — mem si pa gagn sa lokalman."},"missionP2":{"en":"We understand the anxiety of travelling abroad for medical treatment. That is why we handle everything — from finding the right specialist, to your hotel room, your visa, and your return flight. Our job is to let you focus on one thing: your recovery.","fr":"Nous comprenons l''anxiété liée à un voyage à l''étranger pour des soins médicaux. C''est pourquoi nous nous occupons de tout — de la recherche du bon spécialiste à votre chambre d''hôtel, en passant par votre visa et votre vol retour. Notre travail est de vous permettre de vous concentrer sur une seule chose : votre guérison.","kr":"Nou konpran ki li bien stresan pou vwayaze pou al swagn maladi letranze. Se pou sa ki nou okip tou — depi trouv bon dokter la ziska rezerv lotel, viza, ek biye retour. Nou travay se permet ou konsantre zis lor ou gerizon."},"missionP3":{"en":"Our service is always 100% free for patients. We are compensated directly by our hospital partners, never by the patients we serve.","fr":"Notre service est toujours 100% gratuit pour les patients. Nous sommes rémunérés directement par nos hôpitaux partenaires, jamais par les patients que nous aidons.","kr":"Nou servis li touzour 100% gratis pou bann pasian. Se bann lopital partner ki pey nou direk, zame bann pasian ki nou ed."},"pillar1Title":{"en":"JCI / NABH Accredited Hospitals Only","fr":"Uniquement des Hôpitaux Accrédités JCI / NABH","kr":"Zis Lopital Akredite JCI / NABH"},"pillar1Desc":{"en":"We only partner with hospitals that meet the most rigorous global quality and safety standards.","fr":"Nous ne travaillons qu''avec des hôpitaux respectant les normes de sécurité les plus strictes.","kr":"Nou travay zis ar bann lopital ki ena bann pli o standard sekirite."},"pillar2Title":{"en":"Direct Department Head Opinions","fr":"Avis Directs des Chefs de Service","kr":"Lavi Direk Sef Dokter"},"pillar2Desc":{"en":"Your medical reports are reviewed directly by chief surgeons, not automated software.","fr":"Vos rapports médicaux sont examinés directement par les chirurgiens en chef.","kr":"Ou dosie medikal li examine direk par bann sef sirizien."},"pillar3Title":{"en":"Complete Travel Coordination","fr":"Coordination Complète du Voyage","kr":"Kordinasion Vwayaz Konple"},"pillar3Desc":{"en":"Medical visas, flights, companion travel, airport pickup, and dedicated hotel booking.","fr":"Visas médicaux, vols, billets accompagnants, accueil aéroport et réservation hôtel.","kr":"Viza medikal, vol, biye akonpagnan, transpor ek rezervasion lotel."},"pillar4Title":{"en":"Zero Patient Fees","fr":"Zéro Frais pour le Patient","kr":"Zero Fré Pou Pasian"},"pillar4Desc":{"en":"Our guidance and concierge coordination are 100% free of charge for Mauritian patients.","fr":"Notre accompagnement et notre conciergerie sont 100% gratuits pour les patients mauriciens.","kr":"Nou asistans ek kordinasion zot 100% gratis pou bann pasian Morisien."},"ctaTitle":{"en":"Ready to Start Your Journey?","fr":"Prêt à Commencer Votre Parcours ?","kr":"Pare Pou Koumans Ou Vwayaz ?"},"ctaDesc":{"en":"Get a free medical opinion from our partner specialists within 48 hours.","fr":"Obtenez un avis médical gratuit de nos spécialistes partenaires dans les 48 heures.","kr":"Gagn enn lavi medikal gratis avek nou bann dokter partner dan 48h."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('services', 'services', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"Full Concierge Care","fr":"Conciergerie Médicale Complète","kr":"Full Concierge Medikal"},"heroTitle":{"en":"Our Services Cover Every Need","fr":"Nos Services Couvrent Tous Vos Besoins","kr":"Nou Bann Servis Kouver Tou Ou Bizin"},"heroDesc":{"en":"From your first inquiry to post-treatment follow-up, Medical 360 handles every detail of your healthcare journey abroad.","fr":"De votre première demande au suivi post-traitement, Medical 360 s''occupe de chaque détail de votre parcours de santé à l''étranger.","kr":"Depi premie demann ziska swivi apre tretman, Medical 360 okip tou bann detay dan ou vwayaz medikal."},"serviceOpinionTitle":{"en":"1. Free Expert Medical Opinion","fr":"1. Avis Médical d''Expert Gratuit","kr":"1. Lavi Medikal Expert Gratis"},"serviceOpinionDesc":{"en":"Receive treatment plans and transparent cost estimates from top hospital department heads within 48 hours.","fr":"Recevez des plans de traitement et des devis transparents des chefs de service hospitaliers sous 48h.","kr":"Gagn plan tretman ek estimasion pri kler depi bann sef dokter dan 48h."},"serviceTravelTitle":{"en":"2. Medical Visa & Travel Planning","fr":"2. Visa Médical & Organisation du Voyage","kr":"2. Viza Medikal & Plan Voyaz"},"serviceTravelDesc":{"en":"Fast-track visa invitation letters, priority flight bookings with medical luggage allowances, and airline wheelchair assistance.","fr":"Lettres d''invitation visa accélérées, réservations vols prioritaires avec bagages médicaux et assistance.","kr":"Let linvitasion viza vit-vit, rezervasion vol prioritair ek lasistans fotey roulan."},"serviceHospitalTitle":{"en":"3. Priority Hospital Admission","fr":"3. Admission Hospitalière Prioritaire","kr":"3. Ladmision Lopital Prioriter"},"serviceHospitalDesc":{"en":"Skip waiting lists. Direct appointments booked with leading chief surgeons, private rooms, and zero queueing.","fr":"Évitez les listes d''attente. Rendez-vous directs avec les chirurgiens en chef et chambres privées.","kr":"Pa bizin atann. Randevou direk ar bann sef sirizien ek lasam prive."},"serviceTranslationTitle":{"en":"4. Multilingual & Translator Support","fr":"4. Assistance Traducteur & Multilingue","kr":"4. Lasistans Tradiksion & Langaz"},"serviceTranslationDesc":{"en":"Dedicated on-ground language coordinators fluent in English, French, and local languages to assist you in every doctor consultation.","fr":"Coordinateurs locaux bilingues pour vous assister lors de chaque consultation avec les médecins.","kr":"Kordinater lokal pou ed ou dan sak randevou dokter pou tradir tou kler."},"serviceTransferTitle":{"en":"5. Airport VIP Meet & Greet","fr":"5. Accueil VIP & Transferts Aéroport","kr":"5. Lariwe VIP & Transpor Lotel"},"serviceTransferDesc":{"en":"Private ambulance or comfortable chauffeur vehicle waiting upon landing to escort you directly to your hospital or hotel.","fr":"Ambulance privée ou véhicule tout confort à l''atterrissage pour vous conduire directement à l''hôpital ou à l''hôtel.","kr":"Ambilans prive ouswa transpor konfor ki pe atann ou pou amenn ou lopital ouswa lotel."},"serviceRecoveryTitle":{"en":"6. Post-Treatment Remote Follow-Up","fr":"6. Suivi Médical à Distance Post-Traitement","kr":"6. Swivi Medikal A Distans Apre Tretman"},"serviceRecoveryDesc":{"en":"Post-op telemedicine consultations with your operating surgeon once you return home to Mauritius.","fr":"Téléconsultations post-opératoires avec votre chirurgien une fois de retour à l''Île Maurice.","kr":"Konsiltasion video ar ou sirizien kan ou retourn Moris pou fer sir tou pe bien pase."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('specialties', 'specialties', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"Medical Expertise","fr":"Expertise Médicale","kr":"Exspertiz Medikal"},"heroTitle":{"en":"Select Your Specialty","fr":"Sélectionnez Votre Spécialité","kr":"Swazir Ou Spesialite"},"heroDesc":{"en":"Browse our full range of medical specialties. Click any specialty to view procedures, estimated costs, and get a tailored opinion.","fr":"Parcourez notre gamme complète de spécialités médicales. Cliquez sur une spécialité pour voir les procédures, les coûts estimés et obtenir un avis sur mesure.","kr":"Get tou bann spesialite medikal ki nou ofer. Klik lor enn spesialite pou trouv bann tretman, pri estime, ek gagn enn lavi medikal personnaliser."},"guidanceText":{"en":"All procedures include comprehensive pre-operative assessment and international standard surgical care.","fr":"Toutes les interventions incluent un bilan préopératoire complet et des soins chirurgicaux aux standards internationaux.","kr":"Tou bann loperasion inklir bilan konple avan loperasion ek swen o standard internasional."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('hospitals', 'hospitals', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"Our Network","fr":"Notre Réseau","kr":"Nou Rezo"},"heroTitle":{"en":"Associated Hospitals","fr":"Hôpitaux Associés","kr":"Lopital Partner"},"heroDesc":{"en":"Every hospital in our network is internationally accredited. Browse our partner hospitals and explore their specialties, facilities, and patient services.","fr":"Chaque hôpital de notre réseau est accrédité au niveau international. Parcourez nos hôpitaux partenaires et explorez leurs spécialités, leurs installations et leurs services aux patients.","kr":"Sak lopital dan nou rezo ena akreditasion internasional. Get nou bann lopital partner ek explor zot spesialite, fasilite, ek servis pou bann pasian."},"searchPlaceholder":{"en":"Search hospitals by name, city, or country...","fr":"Rechercher des hôpitaux par nom, ville ou pays...","kr":"Rod lopital par nom, lavil ouswa pei..."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('doctors', 'doctors', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"World-Renowned Specialists","fr":"Spécialistes de Renom Mondial","kr":"Dokter Klas Mondial"},"heroTitle":{"en":"Our 7 Elite Medical Specialists","fr":"Nos 7 Chirurgiens et Médecins d''Élite","kr":"Nou 7 Dokter ek Sirizien Spesialist"},"heroDesc":{"en":"Meet our handpicked network of 7 world-leading medical surgeons and consultants who have performed over 100,000 successful surgeries combined.","fr":"Découvrez notre réseau exclusif de 7 chirurgiens et consultants de premier plan ayant réalisé plus de 100 000 interventions réussies.","kr":"Dekouver nou rezo seleksione de 7 dokter ek sirizien klas mondial ki finn fer plis ki 100 000 loperasion a-sikse."},"trustBadgeText":{"en":"Direct Consultation & Second Opinion Available","fr":"Consultation Directe & Deuxième Avis Disponible","kr":"Konsiltasion Direk ek Deziem Lavi Disponib"}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('case-studies', 'case-studies', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"Patient Stories","fr":"Témoignages de Patients","kr":"Zistwar Bann Pasian"},"heroTitle":{"en":"Case Studies","fr":"Études de Cas","kr":"Temwagnaz"},"heroDesc":{"en":"Real stories from real patients. Read how Medical 360 facilitated life-changing treatments for patients from Mauritius and across the Indian Ocean region.","fr":"Des histoires vraies de vrais patients. Lisez comment Medical 360 a facilité des traitements vitaux pour des patients de l''Île Maurice et de l''océan Indien.","kr":"Vre zistwar depi vre pasian. Lir kouma Medical 360 finn ed bann pasian depi Moris ek l''osean Indien gagn tretman ki finn sov zot lavi."},"ctaTitle":{"en":"Could You Be Our Next Success Story?","fr":"Pourriez-vous être notre prochaine success story ?","kr":"Ou kapav vinn nou prosenn zistwar a-sikse?"},"ctaDesc":{"en":"Join thousands of patients who trusted Medical 360 to find them the best care at the right price.","fr":"Rejoignez des milliers de patients qui ont fait confiance à Medical 360 pour trouver les meilleurs soins au bon prix.","kr":"Rezwenn milye pasian ki finn fer Medical 360 konfians pou gagn pli bon swen ek pli bon pri."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('describe-need', 'describe-need', '2026-08-21T06:52:08.868Z', '{"heroTitle":{"en":"Describe Your Need","fr":"Décrivez Votre Besoin","kr":"Dekrir Ou Bizin"},"heroDesc":{"en":"Fill in the form below and our medical team will get back to you with personalised hospital recommendations — free of charge.","fr":"Remplissez le formulaire ci-dessous et notre équipe médicale vous répondra avec des recommandations personnalisées — gratuitement.","kr":"Ranpli form ki anba la e nou lekip medikal pou reponn ou avek bann rekomandasion lopital personalize — pou nanye ditou."},"step1Heading":{"en":"Personal Information","fr":"Informations Personnelles","kr":"Linformasion Personel"},"step2Heading":{"en":"Medical Condition & Specialty","fr":"Condition Médicale & Spécialité","kr":"Kondision Medikal & Spesialite"},"step3Heading":{"en":"Travel & Budget Preferences","fr":"Préférences de Voyage & Budget","kr":"Preferans Voyaz & Bidze"},"step4Heading":{"en":"Review & Submit","fr":"Vérifier & Soumettre","kr":"Revize & Soumet"},"successTitle":{"en":"Inquiry Submitted Successfully!","fr":"Demande Soumise avec Succès !","kr":"Demann Finn Soumet avek Sikse !"},"successDesc":{"en":"Your case has been received. A dedicated Medical 360 case coordinator will contact you within 24 hours.","fr":"Votre dossier a été reçu. Un coordinateur de cas dédié de Medical 360 vous contactera sous 24h.","kr":"Nou finn gagn ou dosie. Enn kordinater Medical 360 pou kontakte ou dan 24h."}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('contact', 'contact', '2026-08-21T06:52:08.868Z', '{"heroLabel":{"en":"Get in Touch","fr":"Contactez-Nous","kr":"Kontak Nou"},"heroTitle":{"en":"Contact Us","fr":"Contact","kr":"Kontak"},"heroDesc":{"en":"Have questions? Our team is available 7 days a week. Reach us by WhatsApp, phone, or email.","fr":"Des questions ? Notre équipe est disponible 7 jours sur 7. Joignez-nous par WhatsApp, téléphone ou email.","kr":"Ena kestion? Nou lekip la 7 zour lor 7. Kontak nou lor WhatsApp, telefonn ouswa email."},"reachUsTitle":{"en":"Reach Us Directly","fr":"Joignez-nous Directement","kr":"Koz Ar Nou Direk"},"officeAddress":{"en":"Med360 Ltd, Level 4, Medical Hub, Port Louis, Mauritius","fr":"Med360 Ltd, Niveau 4, Pôle Médical, Port-Louis, Île Maurice","kr":"Med360 Ltd, Nivo 4, Pôle Médical, Port-Louis, Moris"},"hoursText":{"en":"Mon – Sat: 8:00 AM – 7:00 PM (MUT)\nWhatsApp available 24/7","fr":"Lun – Sam : 8h00 – 19h00 (MUT)\nWhatsApp disponible 24h/24 et 7j/7","kr":"Lindi - Samdi: 08:00 - 19:00 (MUT)\nWhatsApp disponib 24/7"},"emailAddress":{"en":"contact@med360.mu","fr":"contact@med360.mu","kr":"contact@med360.mu"},"phoneNumber":{"en":"+230 59188275","fr":"+230 59188275","kr":"+230 59188275"}}');
INSERT INTO cms_pages (id, name, updated_at, content) VALUES ('footer', 'footer', '2026-08-21T06:52:08.868Z', '{"tagline":{"en":"Medical 360 connects Mauritian patients to accredited hospitals worldwide for cardiac surgery, cancer care, orthopedics, organ transplants, IVF, and more.","fr":"Medical 360 connecte les patients mauriciens aux hôpitaux accrédités du monde entier pour la chirurgie cardiaque, l''oncologie, l''orthopédie, les greffes, la FIV, etc.","kr":"Medical 360 konekte bann pasian Moris ar bann pli bon lopital dan lemond pou kardiolozi, onkolozi, lortopedi, transplantasion, FIV, ek lezot."},"copyrightText":{"en":"Med360 Ltd. All rights reserved. Registered Medical Facilitator in Mauritius.","fr":"Med360 Ltd. Tous droits réservés. Facilitateur médical enregistré à l''Île Maurice.","kr":"Med360 Ltd. Tou drwa rezerve. Fasilitater medikal anrezistre dan Moris."},"disclaimer":{"en":"Medical 360 is a healthcare concierge service and does not provide medical diagnoses directly.","fr":"Medical 360 est un service de conciergerie médicale et ne fournit pas directement de diagnostics médicaux.","kr":"Medical 360 se enn servis konsierzri medikal e li pa donn diagnostik medikal direkteman."}}');

COMMIT;
